insert into kafaa_fl_participants (id, nomination_id, person_id, cohort_id, person_name, person_name_ar, modules_done, project_title, project_question, project_summary, project_sponsor_role, project_status, project_submitted_on, project_reviewed_by, project_review_note, project_decided_on, status, completed_on, history, updated_at) values
('flp:ln-fl-001', 'ln-fl-001', 'w-mnt-01', 'flc-2025', 'Humaid Al Ketbi', 'حميد الكتبي', array['flm-safety','flm-regulation','flm-project','flm-stakeholder','flm-knowledge','flm-future']::text[], 'Keeping senior control-room knowledge when experienced operators retire', 'How should succession and knowledge capture be paced so that retirements never thin a crew below its proven experience?', 'This paper looks at "Keeping senior control-room knowledge when experienced operators retire". It reviews current practice in our area, compares it with published international guidance and proposes three options with their risks, costs and the people they affect.', 'Shift Manager (role card)', 'accepted', '2025-06-01', 'p-training-mgr', null, '2025-06-20', 'completed', '2025-06-30', '[{"at":"2025-06-20T10:00:00Z","status":"project:accepted","by":"p-training-mgr","note":null}]'::jsonb, '2025-06-30T16:00:00Z'),
('flp:ln-fl-002', 'ln-fl-002', 'w-qa-02', 'flc-2025', 'Karim Haddad', 'Karim Haddad', array['flm-safety','flm-regulation','flm-project','flm-stakeholder','flm-knowledge','flm-future']::text[], 'Reading safety-culture trends from field observations', 'Which observation signals give leaders an early, fair picture of safety culture in a team?', 'This paper looks at "Reading safety-culture trends from field observations". It reviews current practice in our area, compares it with published international guidance and proposes three options with their risks, costs and the people they affect.', 'Nuclear Oversight Lead (role card)', 'accepted', '2025-06-01', 'p-training-mgr', null, '2025-06-20', 'completed', '2025-06-30', '[{"at":"2025-06-20T10:00:00Z","status":"project:accepted","by":"p-training-mgr","note":null}]'::jsonb, '2025-06-30T16:00:00Z'),
('flp:ln-fl-003', 'ln-fl-003', 'w-chem-02', 'flc-2025', 'Mansour Al Mazrouei', 'منصور المزروعي', array['flm-safety','flm-regulation','flm-project','flm-stakeholder','flm-knowledge','flm-future']::text[], 'Supplier quality expectations for factory-built modules (concept, no deployment decision implied)', 'Which supplier quality controls would have to move into the factory if modules were built off site?', 'This paper looks at "Supplier quality expectations for factory-built modules (concept, no deployment decision implied)". It reviews current practice in our area, compares it with published international guidance and proposes three options with their risks, costs and the people they affect.', 'Head of Supplier Quality (role card)', 'accepted', '2025-06-01', 'p-training-mgr', null, '2025-06-20', 'completed', '2025-06-30', '[{"at":"2025-06-20T10:00:00Z","status":"project:accepted","by":"p-training-mgr","note":null}]'::jsonb, '2025-06-30T16:00:00Z'),
