('flp:ln-fl-005', 'ln-fl-005', 'w-eng-04', 'flc-2025', 'Thomas Dubois', 'Thomas Dubois', array['flm-safety','flm-regulation','flm-project','flm-stakeholder','flm-knowledge','flm-future']::text[], 'Cross-training chemistry and radiation protection technicians', 'Would a shared foundation year shorten time to independent work without weakening either discipline?', 'This paper looks at "Cross-training chemistry and radiation protection technicians". It reviews current practice in our area, compares it with published international guidance and proposes three options with their risks, costs and the people they affect.', 'Chemistry Superintendent (role card)', 'accepted', '2025-06-01', 'p-training-mgr', null, '2025-06-20', 'completed', '2025-06-30', '[{"at":"2025-06-20T10:00:00Z","status":"project:accepted","by":"p-training-mgr","note":null}]'::jsonb, '2025-06-30T16:00:00Z'),
('flp:ln-fl-006', 'ln-fl-006', 'w-rp-02', 'flc-2025', 'Fatima Al Mazrouei', 'فاطمة المزروعي', array['flm-safety','flm-regulation','flm-project','flm-stakeholder','flm-knowledge','flm-future']::text[], 'A public-communication playbook for planned outages', 'What should communities and partners hear, from whom and when, before and during a planned outage?', 'This paper looks at "A public-communication playbook for planned outages". It reviews current practice in our area, compares it with published international guidance and proposes three options with their risks, costs and the people they affect.', 'Communications Director (role card)', 'accepted', '2025-06-01', 'p-training-mgr', null, '2025-06-20', 'completed', '2025-06-30', '[{"at":"2025-06-20T10:00:00Z","status":"project:accepted","by":"p-training-mgr","note":null}]'::jsonb, '2025-06-30T16:00:00Z'),
